#pragma once
#include "services.hpp"
#include "tests_archive.hpp"
namespace sma {
inline int selfTest(const fs::path& app){
    auto root=app/L"native-test-results"/unique();fs::create_directories(root);SetEnvironmentVariableW(L"SMA_DATA",(root/L"userdata").c_str());std::string report;unsigned count=0;
    auto check=[&](bool good,const std::string& text){if(!good)throw Fault("test",text);report+="PASS "+text+"\n";++count;};
    auto reject=[&](const std::function<void()>& fn,const std::string& name){try{fn();}catch(...){check(true,name);return;}throw Fault("test","Not rejected: "+name);};
    try{
        auto locked=root/L"locked-game";fs::create_directories(locked);write(locked/L"sekiro.exe","fixture, never executed");ensureModsFolder(locked);check(fs::is_directory(locked/L"mods")&&!hasMods(locked),"lock creates missing mods without installed files");write(locked/L"mods"/L"keep.bin","keep");ensureModsFolder(locked);check(read(locked/L"mods"/L"keep.bin")=="keep","lock preserves existing mods");auto invalid=root/L"invalid-game";fs::create_directories(invalid);reject([&]{ensureModsFolder(invalid);},"lock rejects directory without sekiro");check(!fs::exists(invalid/L"mods"),"invalid root remains untouched");auto blocked=root/L"blocked-game";fs::create_directories(blocked);write(blocked/L"sekiro.exe","fixture, never executed");write(blocked/L"mods","blocking file");reject([&]{ensureModsFolder(blocked);},"lock rejects mods file conflict");
        auto j=Json::parse("{\"Language\":\"zh\",\"Files\":[{\"Size\":9007199254740993}],\"Name\":\"\\u5f71\\u6b66\"}");check(j.get("Files").items[0].get("Size").integer()==9007199254740993LL,"exact JSON integer");check(Json::parse(j.dump()).get("Name").str()=="影武","Unicode JSON roundtrip");check(Json::parse("{\"zoom\":1.25,\"exponent\":1e-6}").dump().find("1.25")!=std::string::npos,"Edge decimal preference values");reject([]{Json::parse("{\"x\":1,\"x\":2}");},"duplicate JSON keys");
        reject([&]{child(root,L"../escape");},"path traversal");reject([&]{child(root,L"C:\\escape");},"absolute path");reject([&]{child(root,L"chr/CON.txt");},"device path");reject([&]{child(root,L"chr/f:ads");},"alternate stream");
        auto game=root/L"game",input=root/L"input";fs::create_directories(game);write(game/L"sekiro.exe","fixture, never executed");fs::create_directories(input/L"chr");write(input/L"chr"/L"new.bin","new");
        install(game,app/L"assets",{},false);check(engineMatches(game,app/L"assets"),"engine installation");restore(game);check(!fs::exists(game/L"mods")&&!fs::exists(game/L"dinput8.dll"),"restore original absence");restore(game);check(engineMatches(game,app/L"assets"),"undo restore");write(game/L"mods"/L"keep.bin","keep");
        install(game,app/L"assets",input,true,"fixture","1");check(fs::exists(game/L"mods"/L"keep.bin")&&read(game/L"mods"/L"chr"/L"new.bin")=="new","local merge preserves existing files");
        testFault=[](const std::string& stage){if(stage=="mods")throw Fault("testFault");};reject([&]{install(game,app/L"assets",input,false);},"injected replacement failure");testFault={};check(fs::exists(game/L"mods"/L"keep.bin"),"replacement failure rollback");
        clearMods(game);check(!hasMods(game)&&engineMatches(game,app/L"assets"),"clear preserves engine");restore(game);check(fs::exists(game/L"mods"/L"keep.bin"),"undo clear");
        auto p=Json::object();p["Id"]="fixture";p["Name"]="Fixture";p["Version"]="1";p["Files"]=fingerprints(input);Detection detector;auto result=detector.scan(game,{p});check(result.complete.size()==1,"complete preset plus extra files");write(game/L"mods"/L"chr"/L"new.bin","changed");check(detector.scan(game,{p}).partial.size()==1,"partial preset detected");
        auto seven=app/L"tools"/L"7z.exe",zip=root/L"input.zip";auto creation=run(seven,{L"a",L"-tzip",zip.wstring(),(input/L"chr").wstring()});check(creation.code==0,"ZIP fixture creation");auto unpacked=root/L"unpacked";extract(seven,zip,unpacked);check(read(unpacked/L"chr"/L"new.bin")=="new","safe archive extraction");check(modRoots(unpacked).size()==1,"resource root detection");
        auto catalogAll=catalog(app);check(catalogAll.size()==7,"seven preset catalog");
        for(auto format:{L"7z",L"tar",L"gzip",L"bzip2",L"xz"}){auto archive=root/(std::wstring(L"format.")+format);auto made=run(seven,{L"a",std::wstring(L"-t")+format,archive.wstring(),(input/L"chr"/L"new.bin").wstring()});check(made.code==0,"create "+utf8(format));auto dest=root/(std::wstring(L"extract-")+format);extract(seven,archive,dest);auto content=files(dest);check(content.size()==1&&read(content[0])=="new","extract "+utf8(format));}
        auto secret=root/L"secret.7z";check(run(seven,{L"a",L"-t7z",L"-pfixture-password",L"-mhe=on",secret.wstring(),(input/L"chr").wstring()}).code==0,"create encrypted archive");reject([&]{extract(seven,secret,root/L"secret-bad",L"wrong");},"wrong archive password");extract(seven,secret,root/L"secret-good",L"fixture-password");check(read(root/L"secret-good"/L"chr"/L"new.bin")=="new","encrypted extraction");
        std::string random(16384,' ');uint32_t seed=17;for(auto& c:random){seed=seed*1664525u+1013904223u;c=char(seed>>24);}write(root/L"random.bin",random);auto split=root/L"split.7z";check(run(seven,{L"a",L"-t7z",L"-v2k",split.wstring(),(root/L"random.bin").wstring()}).code==0,"create split archive");split+=L".001";extract(seven,split,root/L"split-good");check(read(root/L"split-good"/L"random.bin")==random,"split archive extraction");
        testFault=[](const std::string& stage){if(stage=="clear")throw Fault("testFault");};reject([&]{clearMods(game);},"injected clear failure");testFault={};check(hasMods(game),"failed clear rolls back");
        auto saved=root/L"saved-snapshot";snapshotTo(game,saved);write(saved/L"mods"/L"keep.bin","corrupt");reject([&]{snapshotMeta(saved);},"corrupt backup rejected");
        auto interrupted=root/L"interrupted";fs::create_directories(interrupted/L"mods");write(interrupted/L"sekiro.exe","fixture, never executed");write(interrupted/L"mods"/L"original.bin","original");auto b=backups(interrupted);snapshotTo(interrupted,b/L"pending");write(interrupted/L"mods"/L"original.bin","interrupted");write(b/L"journal.json","applying");recover(interrupted);check(read(interrupted/L"mods"/L"original.bin")=="original"&&!needsRecovery(interrupted),"interrupted applying recovery");removeOwned(b/L"pending",b);snapshotTo(interrupted,b/L"pending");write(interrupted/L"mods"/L"original.bin","committed");write(b/L"journal.json","committed");recover(interrupted);check(read(interrupted/L"mods"/L"original.bin")=="committed"&&hasBackup(interrupted),"interrupted committed recovery");restore(interrupted);check(read(interrupted/L"mods"/L"original.bin")=="original","recovered backup restorable");
        auto downloadDir=root/L"downloads";fs::create_directories(downloadDir);auto download=p;download["FileName"]="fixture.zip";write(downloadDir/L"fixture (1).zip","fixture");check(downloaded(download,Json::object(),{downloadDir}).size()==1,"browser numbered filename");auto complete=downloadDir/L"fixture (1).zip";write(downloadDir/L"fixture (1).zip.crdownload","pending");reject([&]{requireComplete(complete);},"incomplete download rejected");
        fs::create_directories(root/L"empty-game"/L"mods"/L"parts");check(!hasMods(root/L"empty-game"),"empty folders are not installed mods");
        auto rar=root/L"fixture.rar";testRar(rar);extract(seven,rar,root/L"rar-good");check(read(root/L"rar-good"/L"chr"/L"test.bin")=="fixture","RAR stored fixture extraction");
        auto bad=root/L"traversal.zip";testZip(bad,"../escape.bin");reject([&]{extract(seven,bad,root/L"bad-output");},"archive traversal rejected");check(!fs::exists(root/L"escape.bin"),"archive cannot write outside staging");
        auto linked=root/L"linked.zip";testZip(linked,"chr/link.bin",true);reject([&]{extract(seven,linked,root/L"link-output");},"archive symbolic link rejected");
        report+="TOTAL "+std::to_string(count)+" checks passed\n";write(app/L"native-test-report.txt",report);return 0;
    }catch(const std::exception& e){testFault={};report+="FAIL "+std::string(e.what())+"\n";write(app/L"native-test-report.txt",report);return 1;}
}
}
